+---
+// The Gramaire landing page — a standalone Astro page (outside Starlight's
+// chrome, like /lab) implementing the "Gramaire Site" design: a hero, a live
+// "one file · edit the source" grammar → railroad showcase, three capability
+// tiles, and a light/dark toggle that shares Starlight's `starlight-theme`
+// storage key so the theme carries across to the docs pages.
+import GramaireMark from "../components/GramaireMark.astro";
+import GramaireWordmark from "../components/GramaireWordmark.astro";
+import "@fontsource/ibm-plex-sans/400.css";
+import "@fontsource/ibm-plex-sans/500.css";
+import "@fontsource/ibm-plex-sans/600.css";
+import "@fontsource/ibm-plex-sans/700.css";
+import "@fontsource/ibm-plex-mono/400.css";
+import "@fontsource/ibm-plex-mono/500.css";
+
+const base = import.meta.env.BASE_URL;
+
+// A compact, self-contained grammar the showcase seeds with: valid on its own
+// (literal terminals, no token-class block), so the real engine parses it and
+// draws both rules' railroad diagrams live.
+const SHOWCASE_GRAMMAR = `Expr
+  : Expr '+' Term
+  | Term
+
+Term
+  : Term '*' 'num'
+  | 'num'
+`;
+---
+
+<!doctype html>
+<html lang="en">
+  <head>
+    <meta charset="utf-8" />
+    <meta name="viewport" content="width=device-width, initial-scale=1" />
+    <link rel="icon" type="image/svg+xml" href={`${base}favicon.svg`} />
+    <title>Gramaire — grammars that render themselves</title>
+    <meta
+      name="description"
+      content="An LR parser generator whose source format is Markdown. A .gram.md file renders on GitHub — prose, railroad diagrams, FIRST/FOLLOW tables — and is the exact input the generator reads."
+    />
+    <script is:inline>
+      // No-flash theme: honour a stored choice, else the OS preference. Shares
+      // Starlight's `starlight-theme` key so a toggle here persists to the docs.
+      (() => {
+        try {
+          const stored = localStorage.getItem("starlight-theme");
+          const theme =
+            stored === "light" || stored === "dark"
+              ? stored
+              : window.matchMedia("(prefers-color-scheme: dark)").matches
+                ? "dark"
+                : "light";
+          document.documentElement.dataset.theme = theme;
+        } catch (e) {
+          /* localStorage blocked — fall through to the light default */
+        }
+      })();
+    </script>
+    <style is:global>
