+        max-width: 100%;
+        height: auto;
+      }
+      .rr-figure figcaption {
+        font-family: var(--font-mono);
+        font-size: 12px;
+        font-weight: 600;
+        color: var(--accent);
+        margin-bottom: 4px;
+      }
+      html[data-theme="dark"] .rr-figure .rr-text {
+        fill: var(--fg-secondary);
+      }
+      html[data-theme="dark"] .rr-figure .rr-nonterm {
+        fill: var(--bg-2);
+        stroke: var(--fg-muted);
+      }
+      html[data-theme="dark"] .rr-figure .rr-cap {
+        fill: var(--fg);
+      }
+      html[data-theme="dark"] .rr-figure .rr-track {
+        stroke: var(--fg-faint);
+      }
+
+      /* Tiles */
+      .gx-tiles {
+        display: flex;
+        gap: 14px;
+        flex-wrap: wrap;
+        margin-top: 24px;
+      }
+      .gx-tile {
+        flex: 1;
+        min-width: 180px;
+        border: 1px solid var(--border);
+        border-radius: var(--radius-lg);
+        padding: 20px;
+        background: var(--bg-1);
+      }
+      .gx-tile .big {
+        font-family: var(--font-mono);
+        font-weight: 700;
+        font-size: 28px;
+        letter-spacing: -0.5px;
+        color: var(--accent);
+      }
+      .gx-tile .small {
+        font-size: 13.5px;
+        color: var(--fg-muted);
+        margin-top: 6px;
+        line-height: 1.45;
+      }
+
+      /* Footer */
+      .gx-foot {
+        margin-top: 56px;
+        padding-top: 24px;
+        border-top: 1px solid var(--border);
+        display: flex;
+        gap: 18px;
+        align-items: center;
+        font-family: var(--font-mono);
