+      }
+      .gx-foot a {
+        text-decoration: none;
+      }
+      .gx-foot a:hover {
+        color: var(--accent);
+      }
+
+      @media (max-width: 640px) {
+        .gx-hero h1 {
+          font-size: 40px;
+          letter-spacing: -1.4px;
